  "securityReports.exceptions.gap.device": "Device / source",
  "securityReports.exceptions.gapDetail.device":
    "Sign-in events record only the request's origin (host or network); no device or specific address is stored, so the report cannot name the machine.",
  "securityReports.exceptions.gap.permissionDenied": "General permission refusals",
  "securityReports.exceptions.gapDetail.permissionDenied":
    "The permission gate returns 403 without writing an event, so only escalation refusals are recorded here. Being refused a screen or an action appears in no report.",

