  "securityReports.afterHours.kpi.critical": "Critical events",
  "securityReports.afterHours.gap.workDayStart": "Start of the working day",
  "securityReports.afterHours.gapDetail.workDayStart":
    "Company settings define the weekend days and the length of the working day, but not the hour it starts. The report assumes 08:00 in the company's timezone and says so above — every finding here rests on that assumption until the field exists.",
  "securityReports.afterHours.gap.shifts": "Shifts",
  "securityReports.afterHours.gapDetail.shifts":
    "There is no per-user or per-branch shift roster, so everyone is measured against one working day. An evening-shift employee will always appear here.",
  "securityReports.afterHours.gap.holidays": "Public holidays",
  "securityReports.afterHours.gapDetail.holidays": "There is no holiday calendar in the settings, so a public holiday is measured as an ordinary working day.",

